ALTER TABLE "audit_log" DROP CONSTRAINT "audit_log_action_valid";--> statement-breakpoint
ALTER TABLE "usage_events" ALTER COLUMN "cost_usd" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "usage_events" ADD COLUMN "pricing_status" text DEFAULT 'priced' NOT NULL;--> statement-breakpoint
ALTER TABLE "usage_events" ADD COLUMN "unpriced_reason" text;--> statement-breakpoint
CREATE INDEX "usage_events_unpriced_idx" ON "usage_events" USING btree ("project_id","occurred_at") WHERE "usage_events"."pricing_status" = 'unpriced';--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_valid" CHECK ("audit_log"."action" in ('project.created', 'project.updated', 'price.added', 'price.ended', 'account.created', 'account.role_changed', 'account.password_reset', 'account.sessions_revoked', 'api_key.created', 'api_key.revoked', 'organization.created', 'account.organization_changed', 'usage.repriced'));--> statement-breakpoint
ALTER TABLE "usage_events" ADD CONSTRAINT "usage_events_pricing_status_valid" CHECK (("usage_events"."pricing_status" = 'priced' and "usage_events"."cost_usd" is not null and "usage_events"."unpriced_reason" is null) or ("usage_events"."pricing_status" = 'unpriced' and "usage_events"."cost_usd" is null and "usage_events"."unpriced_reason" in ('no_pricing', 'no_tier_pricing', 'no_batch_pricing', 'no_audio_pricing', 'no_web_search_pricing')));